import * as AngleWorksheet from './worksheet-model.js?v=18';
import {createPDFs as anglePDFs} from './worksheet-pdf.js?v=20';
const freshSeed=()=>crypto.getRandomValues(new Uint32Array(1))[0].toString(36);
export function mountWorksheet(host,{mode,language,back,adapter=null}){const {TIERS,DEFAULT_COUNTS,questionLimit,validateConfig,generateWorksheet}=adapter||AngleWorksheet;const createPDFs=adapter?.createPDFs||anglePDFs;const bm=language==='bm',tr=(a,b)=>bm?b:a;let disposed=false,buffers=null,docs={},variant='student',page=1,task=null,busy=false,renderVersion=0,currentModel=null;const root=document.createElement('section');root.className='worksheet-generator';host.append(root);root.innerHTML=`<button data-back>${tr('← Exploration','← Penerokaan')}</button><h3>${tr('Generate Exercise PDF','Jana PDF Latihan')}</h3><p><strong>${adapter?adapter.title:mode==='straight'?tr('Angles on a Straight Line','Sudut pada Garis Lurus'):tr('Angles Around a Point','Sudut di Sekeliling Titik')}</strong></p><p>${tr('Configure → Preview → Download','Tetapkan → Pratonton → Muat turun')}</p><div class="worksheet-config"><fieldset><legend>${tr('Difficulty tiers','Tahap kesukaran')}</legend><div class="worksheet-actions"><button data-all>${tr('Select All','Pilih Semua')}</button><button data-none>${tr('Clear All','Kosongkan')}</button></div>${TIERS.map((t,i)=>`<label class="worksheet-tier"><input type="checkbox" data-tier="${i+1}" checked> ${tr('Tier','Tahap')} ${i+1} — ${t[bm?1:0]}</label>`).join('')}</fieldset><details><summary>${tr('Advanced settings','Tetapan lanjutan')}</summary>${adapter?`<label><input type="checkbox" data-worked checked>${tr('Include a worked example','Sertakan contoh penyelesaian')}</label><label><input type="checkbox" data-partial checked>${tr('Include model diagrams','Sertakan rajah model')}</label>`:''}<label>${tr('Working space','Ruang kerja')}<select data-space><option value="standard">${tr('Standard','Biasa')}</option><option value="spacious">${tr('More space','Lebih ruang')}</option></select></label>${TIERS.map((t,i)=>`<label>${tr('Tier','Tahap')} ${i+1}: ${tr('questions','soalan')}<input type="number" data-math-mode="integer" min="1" max="${questionLimit(i+1)}" step="1" data-count="${i+1}" value="${DEFAULT_COUNTS[i+1]}"></label>`).join('')}<label>${tr('Optional title','Tajuk pilihan')}<input data-title maxlength="55"></label><label>${tr('Reproducible seed','Benih boleh diulang')}<input data-seed maxlength="40"></label><button data-fit>${tr('Use counts that fit','Gunakan bilangan yang muat')}</button></details></div><p data-counts></p><p data-status role="status" aria-live="polite"></p><button data-generate class="primary">${tr('Generate preview','Jana pratonton')}</button><section data-preview hidden><div data-model-editor></div><div class="worksheet-actions"><button data-edit>${tr('Edit configuration','Ubah tetapan')}</button><button data-regenerate>${tr('Regenerate questions','Jana semula soalan')}</button><label>${tr('Preview','Pratonton')}<select data-variant><option value="student">${tr('Student PDF','PDF Murid')}</option><option value="teacher">${tr('Teacher PDF','PDF Guru')}</option></select></label></div><div class="worksheet-actions"><button data-prev aria-label="${tr('Previous page','Halaman sebelumnya')}">←</button><span data-page></span><button data-next aria-label="${tr('Next page','Halaman seterusnya')}">→</button></div><div class="worksheet-paper"><canvas aria-label="PDF page preview"></canvas></div><div class="worksheet-actions"><button data-download="student">${tr('Download Student PDF','Muat turun PDF Murid')}</button><button data-download="teacher">${tr('Download Teacher PDF','Muat turun PDF Guru')}</button></div></section>`;
 const get=s=>root.querySelector(s),all=s=>[...root.querySelectorAll(s)],config=()=>({mode,language,tiers:all('[data-tier]:checked').map(e=>+e.dataset.tier),counts:Object.fromEntries(all('[data-count]').map(e=>[e.dataset.count,+e.value])),space:get('[data-space]').value,title:get('[data-title]').value,seed:get('[data-seed]').value,worked:get('[data-worked]')?.checked??true,partial:get('[data-partial]')?.checked??true});get('[data-seed]').value=freshSeed();get('[data-back]').onclick=back;
 function update(){const c=config(),errors=validateConfig(c);get('[data-counts]').textContent=tr(`${c.tiers.length} worksheet pages + ${c.tiers.length} additional teacher answer pages.`,`${c.tiers.length} halaman latihan + ${c.tiers.length} halaman jawapan guru tambahan.`);get('[data-status]').textContent=errors.join(' ');get('[data-generate]').disabled=busy||errors.length>0;all('[data-count]').forEach(e=>e.max=questionLimit(+e.dataset.count,c.space));}
 root.querySelector('.worksheet-config').addEventListener('input',update);root.querySelector('.worksheet-config').addEventListener('change',update);get('[data-all]').onclick=()=>{all('[data-tier]').forEach(e=>e.checked=true);update()};get('[data-none]').onclick=()=>{all('[data-tier]').forEach(e=>e.checked=false);update()};get('[data-fit]').onclick=()=>{const c=config();all('[data-count]').forEach(e=>e.value=Math.max(1,Math.min(+e.value||1,questionLimit(+e.dataset.count,c.space))));update()};
 async function preview(){const version=++renderVersion;task?.cancel();const doc=docs[variant];if(!doc||disposed)return;page=Math.min(page,doc.numPages);get('[data-page]').textContent=`${page} / ${doc.numPages}`;get('[data-prev]').disabled=page===1;get('[data-next]').disabled=page===doc.numPages;const p=await doc.getPage(page);if(disposed||version!==renderVersion)return;const canvas=get('canvas'),viewport=p.getViewport({scale:1.5});canvas.width=viewport.width;canvas.height=viewport.height;task=p.render({canvasContext:canvas.getContext('2d'),viewport});try{await task.promise}catch(e){if(e.name!=='RenderingCancelledException')throw e;}}
 async function generate(regenerate=false,override=null){if(busy)return;if(regenerate)get('[data-seed]').value=freshSeed();update();if(validateConfig(config()).length)return;busy=true;all('button,input,select').filter(e=>!e.hasAttribute('data-back')).forEach(e=>e.disabled=true);get('[data-generate]').disabled=true;get('[data-regenerate]').disabled=true;get('[data-status]').textContent=tr('Preparing print pages…','Menyediakan halaman cetakan…');try{const model=override||generateWorksheet(config());const result=await createPDFs(model);const pdfjs=await import('./vendor/pdf.min.mjs');pdfjs.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdf.worker.min.mjs',import.meta.url).href;if(disposed)return;task?.cancel();for(const doc of Object.values(docs))await doc.destroy();docs={};buffers=result;currentModel=model;for(const type of ['student','teacher'])docs[type]=await pdfjs.getDocument({data:new Uint8Array(result[type].slice(0)),isEvalSupported:false}).promise;if(disposed){for(const doc of Object.values(docs))doc.destroy();return;}page=1;get('[data-preview]').hidden=false;get('.worksheet-config').hidden=true;get('[data-generate]').hidden=true;get('[data-status]').textContent=tr('Ready. Both downloads contain the same worksheet questions.','Sedia. Kedua-dua muat turun mengandungi soalan latihan yang sama.');await preview();}catch(e){if(!disposed)get('[data-status]').textContent=e.message;}finally{busy=false;if(!disposed){all('button,input,select').forEach(e=>e.disabled=false);get('[data-generate]').disabled=validateConfig(config()).length>0;get('[data-prev]').disabled=page===1;get('[data-next]').disabled=page===docs[variant]?.numPages;if(adapter?.mountEditor&&currentModel)adapter.mountEditor(get('[data-model-editor]'),currentModel,next=>generate(false,next));}}}
 get('[data-generate]').onclick=()=>generate();get('[data-regenerate]').onclick=()=>generate(true);get('[data-edit]').onclick=()=>{get('.worksheet-config').hidden=false;get('[data-generate]').hidden=false;get('[data-preview]').hidden=true;update()};get('[data-variant]').onchange=()=>{variant=get('[data-variant]').value;page=1;preview()};get('[data-prev]').onclick=()=>{page--;preview()};get('[data-next]').onclick=()=>{page++;preview()};all('[data-download]').forEach(b=>b.onclick=()=>{if(!buffers)return;const url=URL.createObjectURL(new Blob([buffers[b.dataset.download]],{type:'application/pdf'})),a=document.createElement('a');a.href=url;a.download=`${adapter?'bar-model':'angles-'+mode}-${b.dataset.download}.pdf`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});update();return()=>{disposed=true;renderVersion++;task?.cancel();for(const doc of Object.values(docs))doc.destroy();root.remove()};}
